export const layouts=['inbox','board','briefs'];
export function inferBlueprint(prompt){const text=prompt.toLowerCase();if(/support|customer|ticket|refund|help.?desk/.test(text))return 'support';if(/sales|lead|prospect|outreach|crm/.test(text))return 'sales';if(/research|report|brief|market|competitor/.test(text))return 'research';if(/recruit|hiring|candidate|resume|applicant/.test(text))return 'hiring';if(/epc|weld|manufactur|quality exception|nonconform/.test(text))return 'quality';return 'custom';}
export function projectBlueprint(p){return blueprints[p.blueprintId]||blueprints.custom;}
export function makeBlueprintState(id){const b=blueprints[id]||blueprints.custom;return {blueprintId:b.id,layout:b.layout,entity:b.entity,plural:b.plural,collection:b.collection,headline:b.headline,stages:[...b.stages],fields:[...b.fields],agents:structuredClone(b.agents),records:structuredClone(b.records)};}
